function styleableRelative(parts, fallback) {
  const rendered = parts.map(({ type, value }) => {
    if (type === "integer") return `<span class="local-time-value">${escapeHtml(value)}</span>`
    return escapeHtml(value)
  }).join("")

  return parts.some(({ type }) => type === "integer") ? rendered : `<span class="local-time-value">${escapeHtml(fallback)}</span>`
}

class AgoFormatter {
  constructor(locale, strings = {}) {
    this.rtf = new Intl.RelativeTimeFormat(locale, { numeric: "always", style: "long" })
    this.strings = strings
  }

  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return this.#value(years, "year")
    if (months >= 1) return this.#value(months, "month")
    if (weeks >= 1) return this.#value(weeks, "week")
    if (days >= 1) return this.#value(days, "day")
    if (hours >= 1) return this.#value(hours, "hour")
    if (minutes >= 1) return this.#value(minutes, "minute")

    return this.strings.soon || this.#value(0, "second")
  }

  #value(quantity, unit) {
    return this.rtf.format(-Math.floor(quantity), unit)
  }
}

class DaysAgoFormatter {
  constructor(locale) {
    this.rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto", style: "long" })
  }

  format(date) {
    const days = differenceInDays(date, new Date())
    const value = Math.min(days, 0)

    return styleableRelative(this.rtf.formatToParts(value, "day"), this.rtf.format(value, "day"))
  }
}

class DaysAgoOrWeekdayFormatter {
  constructor(locale) {
    this.locale = locale
    this.rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto", style: "long" })
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) {
      return new DaysAgoFormatter(this.locale).format(date)
    } else {
      return new Intl.DateTimeFormat(this.locale, { weekday: "long", month: "long", day: "numeric" }).format(date)
    }
  }
}

class InDaysFormatter {
  constructor(locale) {
    this.rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto", style: "long" })
  }

  format(date) {
    const days = differenceInDays(new Date(), date)
    const value = Math.max(days, 0)

    return styleableRelative(this.rtf.formatToParts(value, "day"), this.rtf.format(value, "day"))
  }
}

class TimeOrDateFormatter {
  constructor(locale) {
    this.locale = locale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days >= 1) {
      return new Intl.DateTimeFormat(this.locale, { month: "short", day: "numeric" }).format(date)
    } else {
      return new Intl.DateTimeFormat(this.locale, { timeStyle: "short" }).format(date)
    }
  }
}
